-- iBoost — migration 0033
-- Education CMS: move lessons from code into the DB so they can be
-- managed from the admin (list / edit content / add / reorder).
--
-- Two tables:
--   education_chapters — chapter structure (number, title, tagline,
--                        optional score_gate to lock a chapter).
--   education_lessons  — lessons. body is JSONB: an array of content
--                        blocks ({h}/{p}/{list}/{steps}/{callout}),
--                        the same block model the renderer already uses.
--
-- progress_key is the STABLE lesson id (f1, l3, m2…). lesson_progress
-- rows key on this (text), so existing progress stays valid after the
-- move. The uuid id is internal; progress_key is the public stable key.
--
-- RLS: lessons + chapters are readable by any authenticated member
-- (education is free to all). Writes go through the admin backend with
-- the service key (bypasses RLS), same as every other admin write.
--
-- Seeded with the 17 lessons that previously lived in code. After this
-- migration the DB is the source of truth; the code files are removed
-- once the customer page reads from the API (Step B).
--
-- Additive + idempotent-ish (drops/recreates seed rows by slug).

create table if not exists public.education_chapters (
  id uuid primary key default gen_random_uuid(),
  number integer not null,
  title text not null,
  tagline text,
  score_gate integer,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (number)
);

create table if not exists public.education_lessons (
  id uuid primary key default gen_random_uuid(),
  chapter_id uuid not null references public.education_chapters(id) on delete cascade,
  progress_key text not null unique,
  slug text not null unique,
  title text not null,
  minutes integer not null default 3,
  intro text,
  body jsonb not null default '[]'::jsonb,
  sort_order integer not null default 0,
  is_published boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists education_lessons_chapter_idx on public.education_lessons (chapter_id);

alter table public.education_chapters enable row level security;
alter table public.education_lessons enable row level security;

drop policy if exists "education_chapters: members read" on public.education_chapters;
create policy "education_chapters: members read" on public.education_chapters
  for select using (auth.role() = 'authenticated');

drop policy if exists "education_lessons: members read" on public.education_lessons;
create policy "education_lessons: members read" on public.education_lessons
  for select using (auth.role() = 'authenticated');

-- ============================================================
-- Seed: the 17 lessons that previously lived in code.
-- Re-runnable: delete existing seed rows by slug, then re-insert.
-- ============================================================
delete from public.education_lessons where slug in ('what-a-credit-score-measures', 'five-factors-ranked', 'utilization-calculated', 'hard-vs-soft-pulls', 'reading-your-report', 'credit-canada-vs-us', 'when-to-pay-your-card', 'credit-limit-increase', 'disputing-an-error', 'thin-file-quick-wins', 'history-that-compounds', 'new-accounts-and-closures', 'recovering-after-a-miss', 'avoiding-credit-scams', 'beyond-the-score', 'file-mortgage-ready', 'debt-to-income');
delete from public.education_chapters where number in (1, 2, 3, 4);

with ch as (
  insert into public.education_chapters (number, title, tagline, score_gate)
  values (1, 'Foundations', 'Start here if you’re new to credit.', null)
  returning id
)
insert into public.education_lessons (chapter_id, progress_key, slug, title, minutes, intro, body, sort_order)
values
  ((select id from ch), 'f1', 'what-a-credit-score-measures', 'What a credit score actually measures', 3, 'Before you can improve a number, it helps to know exactly what it’s measuring. A credit score isn’t a judgment of you as a person — it’s a prediction.', '[{"h":"What the number is actually predicting"},{"p":"A credit score is a three-digit number, usually between 300 and 900 in Canada (300–850 in the US), that lenders use to estimate one thing: <strong>how likely you are to repay borrowed money on time.</strong> That’s it. It doesn’t measure your income, your savings, your net worth, or how responsible you are in general — only your track record and current behaviour with credit."},{"p":"Think of it like a weather forecast. A forecast doesn’t know for certain whether it’ll rain tomorrow; it looks at patterns and gives a probability. Your score does the same with repayment: it turns your credit history into a single number a lender can read in seconds."},{"callout":"A higher score doesn’t mean you’re “good with money.” It means the data suggests a lower risk of missed payments. Those are different things — and that distinction is good news, because it means the score responds to specific, changeable behaviour."},{"h":"Who calculates it"},{"p":"In Canada, two main credit bureaus — <strong>Equifax</strong> and <strong>TransUnion</strong> — collect information about your credit accounts from lenders. They each maintain a file on you, and a score is calculated from that file. Because the two bureaus don’t always hold identical information, it’s normal to have slightly different scores at each."},{"p":"The lenders you borrow from report to these bureaus, usually monthly. Your file is a rolling record of that reported activity — which is why your score moves over time as new information comes in."},{"h":"What goes into the file"},{"p":"Your credit file generally contains:"},{"list":["Your credit accounts (cards, loans, lines of credit) — when each was opened, the limit or original amount, and the current balance","Your payment history on each account — whether payments arrived on time, and any that were late","Recent applications for credit (these show up as “inquiries”)","Public-record items like bankruptcies or accounts sent to collections","Basic identifying information — name, address history, date of birth"]},{"p":"Notably, your file does <em>not</em> contain your salary, your bank balance, your job title, or your spending at specific stores. The score is built only from credit-related data."},{"h":"Why it matters"},{"p":"The score is the gatekeeper for a lot of everyday financial life: whether you’re approved for a card or loan, the interest rate you’re offered, sometimes whether you’re approved to rent an apartment or get a phone plan. A better score generally means access to more credit at lower cost — which, over a mortgage or car loan, can add up to real money."},{"p":"The encouraging part: because the score is built from specific behaviours — paying on time, how much of your available credit you use, how long your accounts have been open — it’s something you can influence. The rest of this chapter breaks down each of those levers."},{"callout":"Takeaway: your credit score is a repayment-risk prediction built from your credit file at Equifax and TransUnion. It doesn’t measure income or character — only credit behaviour. That’s why it can be improved deliberately."}]'::jsonb, 0),
  ((select id from ch), 'f2', 'five-factors-ranked', 'The five factors, ranked by impact', 4, 'Your score isn’t a mystery formula. It’s built from five categories of information — and they don’t carry equal weight. Knowing which matter most tells you where to focus.', '[{"h":"The five factors"},{"p":"Most scoring models weigh roughly the same five things. The exact percentages vary by model and bureau, but the <em>order</em> is remarkably consistent. From most to least influential:"},{"h":"1. Payment history — the biggest factor"},{"p":"Whether you pay on time, every time. This is consistently the single largest piece of most scores. A long run of on-time payments builds the score steadily; a missed payment can set it back noticeably. Nothing else you do matters as much as paying on time."},{"h":"2. Amounts owed (credit utilization)"},{"p":"How much of your available credit you’re using right now. Using a small share of your limits generally helps; running balances close to your limits generally hurts. This factor is powerful <em>and</em> fast-moving — it can change month to month, which makes it the most actionable lever in the short term. There’s a whole lesson on it next."},{"h":"3. Length of credit history"},{"p":"How long your accounts have been open, and the average age across them. Older is better. This is why closing your oldest card can backfire, and why time itself quietly improves your score as accounts age."},{"h":"4. Credit mix"},{"p":"The variety of credit types you manage — revolving (cards) versus instalment (loans). A mix can help modestly, but this is a minor factor. It’s not worth taking on a loan you don’t need just to “diversify.”"},{"h":"5. New credit / inquiries"},{"p":"How many new accounts and applications you’ve had recently. A burst of applications in a short window can ding the score temporarily, because it can signal risk. This is the smallest factor and tends to recover with time."},{"callout":"Where to focus: the top two — payment history and utilization — drive the large majority of your score and are the most within your control. The bottom three matter, but chasing them is rarely worth much effort."},{"h":"A useful way to think about it"},{"p":"Payment history is the foundation; you protect it by never missing a due date. Utilization is the dial you can turn quickly. The other three mostly reward patience and leaving good accounts alone. If you do nothing else, get those top two right."}]'::jsonb, 1),
  ((select id from ch), 'f3', 'utilization-calculated', 'How credit utilization is really calculated', 4, 'Credit utilization is the most misunderstood number in credit — and one of the most powerful. The good news: once you see how it’s calculated, it becomes one of the easiest levers to pull.', '[{"h":"The basic formula"},{"p":"Utilization is simply how much of your available revolving credit you’re using, expressed as a percentage:"},{"callout":"Utilization = balance ÷ credit limit. A $300 balance on a $1,000 limit is 30% utilization."},{"p":"It applies to revolving credit — credit cards and lines of credit — not to instalment loans like a car loan or mortgage. It’s measured both per-card and across all your revolving accounts combined."},{"h":"Lower is generally better"},{"p":"As a general rule, lower utilization is read as lower risk. Many people see meaningful benefit from keeping utilization in the low double digits or below. Maxing out a card — sitting near 100% — is one of the things that weighs most heavily against a score, even if you always pay on time."},{"p":"It’s not about carrying a balance or paying interest. You can use a card heavily and pay it in full and still show high utilization, because of <em>when</em> the number is measured."},{"h":"The timing trick most people miss"},{"p":"Here’s the part that surprises people. Utilization is usually measured from the balance reported on your <strong>statement date</strong> — not your payment due date. The card issuer reports your statement balance to the bureau. So even if you pay in full every month, if you charge a lot before the statement closes, a high balance gets reported."},{"steps":["Your statement closes on, say, the 3rd — whatever balance is showing that day is what typically gets reported.","Your payment is due later, around the 28th.","If you pay down the balance <em>before</em> the statement closes, a lower number gets reported — and your utilization looks lower."]},{"p":"This means two people who spend identically can show very different utilization, purely based on timing. The next chapter’s lesson on <em>when</em> to pay your card builds directly on this."},{"h":"Per-card vs overall"},{"p":"Both matter. One card near its limit can weigh on your score even if your overall utilization is low. Spreading balances across cards, or paying down the most-utilized card first, can help the per-card picture."},{"callout":"Takeaway: utilization = balance ÷ limit, measured at statement time. It’s powerful and it moves fast, which makes it the best short-term lever you have. Lower, and paid before the statement closes, generally helps most."}]'::jsonb, 2),
  ((select id from ch), 'f4', 'hard-vs-soft-pulls', 'Hard pulls vs soft pulls — and when each matters', 3, 'Not every check of your credit affects your score. Knowing the difference between a hard pull and a soft pull keeps you from worrying about the harmless ones — and being careless with the ones that count.', '[{"h":"Two kinds of credit checks"},{"p":"Any time someone looks at your credit file, it’s recorded as an inquiry. There are two types, and only one affects your score."},{"h":"Soft pulls — no score impact"},{"p":"A soft pull (or soft inquiry) happens when your credit is checked but <strong>not</strong> as part of you applying to borrow. These don’t affect your score at all. Examples:"},{"list":["Checking your own credit score (including through a service like this one)","A lender pre-screening you for an offer you didn’t apply for","An existing lender reviewing your account","Some background or identity checks"]},{"p":"You can check your own credit as often as you like. It is a soft pull every time and will never lower your score — a myth worth putting to rest."},{"h":"Hard pulls — a small, temporary impact"},{"p":"A hard pull (or hard inquiry) happens when you <em>apply</em> for credit and the lender checks your file to make a decision — a new credit card, a loan, a mortgage, sometimes a rental or phone contract. A hard pull can lower your score modestly, usually for a short period, and it stays visible on your report for a while even after the score effect fades."},{"p":"One hard pull is generally minor. The concern is many in a short window, which can suggest you’re taking on risk quickly."},{"h":"The rate-shopping exception"},{"p":"Scoring models generally understand that shopping for one loan — say a mortgage or car loan — means several lenders checking your file in a short span. Many models group similar inquiries within a short window (often a couple of weeks) so that rate-shopping for a single loan counts as roughly one inquiry, not many. So comparing offers for the same loan is usually fine."},{"callout":"Takeaway: checking your own credit is always a soft pull — do it freely. Applying for new credit is a hard pull — minor on its own, but space out applications you don’t need, and don’t fear comparing rates for the same loan."}]'::jsonb, 3),
  ((select id from ch), 'f5', 'reading-your-report', 'Reading your credit report without panicking', 8, 'Your credit report can look like a wall of codes and dates. But it’s organized into a handful of sections, and once you know what each one is telling you, it stops being intimidating.', '[{"h":"Report vs score"},{"p":"First, a distinction. Your credit <strong>report</strong> is the detailed file — every account, payment, and inquiry. Your credit <strong>score</strong> is a number calculated from that report. The report is the raw material; the score is the summary. When you want to understand <em>why</em> your score is what it is, you read the report."},{"h":"The main sections"},{"p":"Most reports are organized into these parts:"},{"h":"Personal information"},{"p":"Your name, current and past addresses, date of birth, and sometimes employment. Worth a glance: errors here (an address you never lived at, a misspelled name) can sometimes signal mixed files or, rarely, fraud."},{"h":"Accounts (or “tradelines”)"},{"p":"The heart of the report. Each credit account shows the type, the date opened, the limit or loan amount, the current balance, and a month-by-month payment history. This is where you’ll see on-time payments — and any that were late, usually marked by how many days late they went (30, 60, 90+)."},{"h":"Inquiries"},{"p":"A list of who checked your credit and when. Hard inquiries (from your applications) and soft inquiries (everything else) are usually listed separately. Only the hard ones affected your score."},{"h":"Public records and collections"},{"p":"Items like bankruptcies, or accounts that were sent to a collection agency. These are the most serious negative items and tend to weigh heavily."},{"h":"How to read it without panicking"},{"p":"Go section by section, slowly. Most of what you see will be routine. Focus your attention on three things:"},{"steps":["Late-payment marks — are they accurate? A late payment you actually made on time is worth disputing (there’s a lesson on that).","Accounts you don’t recognize — these can be errors or, occasionally, fraud, and are worth investigating.","Balances and limits — do they look right? Outdated limits can distort your utilization."]},{"callout":"Takeaway: the report is just a few sections — personal info, accounts, inquiries, and public records/collections. Read it section by section, and focus on what’s inaccurate or unfamiliar. You’re reviewing for errors, not bracing for a verdict."},{"p":"In Canada you’re entitled to request your credit report from each bureau. Reviewing it periodically is one of the simplest habits for catching problems early."}]'::jsonb, 4),
  ((select id from ch), 'f6', 'credit-canada-vs-us', 'Credit in Canada vs the US — what’s different', 4, 'If you’ve moved between Canada and the US — or read US credit advice online while living in Canada — some of it won’t quite fit. The systems rhyme, but they don’t match. Here’s what actually differs.', '[{"h":"The big one: credit does not cross the border"},{"p":"This catches many newcomers off guard. Your credit history in one country generally <strong>does not transfer</strong> to the other. Someone with an excellent decades-long file in the US can arrive in Canada and effectively start from zero. The bureaus operate separately in each country, and a lender in one can’t see your file in the other."},{"callout":"If you’re new to Canada (or new to the US), expect to build a fresh credit history from scratch, regardless of how strong your record was back home. It’s frustrating, but it’s normal — and it’s buildable."},{"h":"Score ranges differ"},{"p":"In Canada, common score ranges run roughly 300–900. In the US, the most familiar ranges run 300–850. So a “good” number isn’t directly comparable across the two — the scales are different."},{"h":"Same bureaus, different scope"},{"p":"Equifax and TransUnion operate in both countries, but as separate national operations with separate data. (The US also has Experian as a major third bureau; its consumer presence in Canada is more limited.) So “check all your bureaus” means different things depending on where you are."},{"h":"What’s the same"},{"p":"The fundamentals carry over. In both countries, paying on time and keeping utilization low are the dominant levers. The five-factor framework holds. The mechanics of statements, due dates, hard versus soft pulls — all broadly similar. So the <em>habits</em> you learn here work on either side of the border; it’s the <em>files</em> that don’t travel."},{"h":"Building credit as a newcomer"},{"p":"Generally, the path to building a fresh file looks similar in both countries: start with an accessible product (such as a secured card or an entry-level account), use it lightly, pay it on time, and let history accumulate. The lesson on thin files covers this in more depth."},{"callout":"Takeaway: credit history doesn’t cross the border, and the score scales differ (Canada ~300–900, US 300–850). But the core habits — pay on time, keep utilization low — are universal. If you’ve relocated, plan to rebuild, not transfer."}]'::jsonb, 5);

with ch as (
  insert into public.education_chapters (number, title, tagline, score_gate)
  values (2, 'The fast levers', 'Things you can change this week to nudge your score up.', null)
  returning id
)
insert into public.education_lessons (chapter_id, progress_key, slug, title, minutes, intro, body, sort_order)
values
  ((select id from ch), 'l1', 'when-to-pay-your-card', 'When to actually pay your credit card', 3, 'Most people think paying their card on time is the whole game. Paying on time is essential — but <em>when</em> in the cycle you pay can change how your credit looks, even if your spending never changes.', '[{"h":"Two dates that aren’t the same"},{"p":"Every credit card has two key dates each month, and confusing them is common:"},{"list":["<strong>Statement (closing) date</strong> — the day your billing cycle ends and your statement is generated. The balance on this day is typically what the card reports to the credit bureau.","<strong>Due date</strong> — the day your minimum payment must arrive to avoid a late mark and interest. Usually a few weeks after the statement date."]},{"p":"Paying by the due date is what protects your payment history — the most important factor. But the balance reported to the bureau is usually snapshotted at the <em>statement</em> date. That gap is the lever."},{"h":"Why this matters for utilization"},{"p":"Recall that utilization = balance ÷ limit, measured from the reported balance. If you charge heavily and let the statement close on a big balance, high utilization gets reported — even if you then pay it all off by the due date and never owe a cent of interest."},{"h":"The timing approach"},{"p":"For many people, the practical takeaway is:"},{"steps":["Always pay at least the minimum by the <strong>due date</strong> — this is non-negotiable; it protects payment history and avoids interest and fees.","If you want lower reported utilization, consider paying down the balance <em>before</em> the <strong>statement date</strong>, so a smaller number gets reported.","Some people make an extra mid-cycle payment for exactly this reason — it keeps the reported balance low without changing what they actually spend."]},{"callout":"Paying by the due date protects your payment history. Paying before the statement date shapes your reported utilization. They’re two different goals served by two different dates."},{"h":"A note on interest"},{"p":"To avoid interest on purchases, the general rule is to pay your <em>statement balance in full</em> by the due date each month. Paying early to manage utilization doesn’t change that — just make sure whatever remains at the due date is covered."},{"p":"None of this requires spending less or carrying a balance. It’s the same money, timed with awareness of when the snapshot is taken."}]'::jsonb, 0),
  ((select id from ch), 'l2', 'credit-limit-increase', 'Asking for a credit limit increase the right way', 4, 'Asking for a higher limit can help your utilization without you spending or paying any differently — because if your balance stays the same and your limit goes up, your utilization goes down. But there’s a right way to ask.', '[{"h":"Why a higher limit can help"},{"p":"Utilization is balance ÷ limit. Raise the limit and — assuming your balance doesn’t rise to match — the ratio drops. Example: a $500 balance on a $1,000 limit is 50%. The same $500 on a $2,000 limit is 25%. Same spending, lower utilization, purely from the larger denominator."},{"callout":"The benefit only holds if your spending stays put. A higher limit that you proceed to fill up doesn’t help — it can hurt. The tactic works for people whose balances are already under control."},{"h":"Soft pull or hard pull?"},{"p":"This is the key question to ask before requesting. Some issuers grant a limit increase with a <strong>soft</strong> pull (no score impact); others run a <strong>hard</strong> pull (a small, temporary impact). Policies vary by issuer and over time. It’s reasonable to ask the issuer which kind of inquiry a request will trigger before you proceed."},{"h":"How to ask"},{"steps":["Many issuers let you request an increase in-app or online — often the simplest route.","Before requesting, check (or ask) whether it triggers a hard or soft pull.","A stronger case generally helps: a history of on-time payments, perhaps a rise in income since you opened the account, and not having asked very recently.","If declined, that’s okay — you can usually try again later once more positive history has built."]},{"h":"Things to keep in mind"},{"p":"A higher limit is a tool, not free money. The point is the improved ratio, not the extra spending room. For someone working to keep balances low, a limit increase obtained the right way can be one of the cleaner utilization wins available — because it requires no change in behaviour, only a larger denominator."},{"callout":"Takeaway: a higher limit lowers utilization if your balance holds steady. Ask whether the request is a soft or hard pull first, make the request when your history is strong, and resist the urge to spend into the new room."}]'::jsonb, 1),
  ((select id from ch), 'l3', 'disputing-an-error', 'Disputing an error on your report', 5, 'Credit reports contain mistakes more often than people expect — a payment marked late that wasn’t, an account that isn’t yours, an outdated balance. You have the right to dispute errors, and correcting them can matter.', '[{"h":"Why errors are worth catching"},{"p":"Because your score is built from your report, an error in the report can drag down the score for no real reason. A single late-payment mark that shouldn’t be there, or an account that isn’t yours, can have an outsized effect — especially since payment history is the biggest factor."},{"h":"Common errors to look for"},{"list":["A payment reported late that you actually made on time","An account that isn’t yours (possible mixed file, or fraud)","A balance or credit limit that’s wrong or out of date","A debt shown as unpaid that you’ve already settled","Duplicate listings of the same account","Outdated negative items that should have aged off"]},{"h":"How the dispute process generally works"},{"p":"In both Canada and the US, you have the right to dispute information you believe is inaccurate, and the bureau is required to investigate. The general shape of the process:"},{"steps":["Get your report and identify the specific item you believe is wrong.","File a dispute with the credit bureau reporting it (Equifax and/or TransUnion). Each bureau has a process for this — online, by mail, or by phone.","Provide any supporting documentation you have (statements, payment confirmations, letters).","The bureau investigates with the lender that reported the item, and responds within the timeframe set by law.","If the item is found to be inaccurate, it’s corrected or removed. If you disagree with the outcome, you generally have further options, including adding a statement to your file."]},{"callout":"A dispute is for information that is genuinely inaccurate, incomplete, or outdated. Accurate negative information — a payment you really did miss — generally can’t be disputed away; it ages off over time instead."},{"h":"A caution about “credit repair” promises"},{"p":"Be wary of anyone promising to “delete” accurate negative items or guaranteeing a specific score jump for a fee. You can dispute genuine errors yourself, at no cost, directly with the bureaus. There’s a dedicated lesson on spotting credit-repair scams."},{"p":"This lesson is general information, not legal advice — if you’re dealing with a complex or contested item, you may want guidance specific to your situation."}]'::jsonb, 2),
  ((select id from ch), 'l4', 'thin-file-quick-wins', 'The quickest wins for a thin credit file', 4, 'A “thin file” means you don’t have much credit history yet — common for newcomers, young adults, or anyone who’s avoided credit. The challenge: you need credit to build credit. Here are the usual on-ramps.', '[{"h":"What a thin file is"},{"p":"Scoring models need data to work with. If you have few or no accounts, there isn’t enough history to generate a strong score — or sometimes any score at all. This isn’t a bad mark; it’s an empty page. The goal is simply to start writing on it, responsibly."},{"h":"Common starting points"},{"p":"These are typical tools people use to begin building a file. Availability and terms vary by lender and country."},{"h":"Secured credit cards"},{"p":"A secured card requires a refundable deposit that usually sets your limit. Because the deposit reduces the lender’s risk, these are generally accessible even with no history. Used lightly and paid on time, a secured card reports to the bureaus like any card and builds history. Many people later graduate to a standard card."},{"h":"Becoming an authorized user"},{"p":"A family member or trusted person can add you as an authorized user on their card. If the account is well-managed, its history may report on your file too. The flip side: if they mismanage it, that can affect you — so it depends entirely on the primary account holder’s habits."},{"h":"Credit-builder products"},{"p":"Some lenders offer products specifically designed to build credit — for example, small instalment arrangements where your on-time payments are reported. Terms vary; read them carefully and confirm the product actually reports to the bureaus, since one that doesn’t report won’t build anything."},{"h":"The habits that make any of them work"},{"steps":["Use the account — a card that sits unused builds little. Small, regular purchases are enough.","Pay on time, every time — this is the foundation of the whole file.","Keep utilization low — don’t run the limit up just because it’s there.","Be patient — history is partly about time. A few months in, a file starts to take shape; longer is better."]},{"callout":"Takeaway: building from a thin file usually means starting with an accessible product (often a secured card), using it lightly, and paying on time while history accumulates. The tool matters less than the habit — and confirm anything you use actually reports to the bureaus."}]'::jsonb, 3);

with ch as (
  insert into public.education_chapters (number, title, tagline, score_gate)
  values (3, 'Building & sustaining', 'The longer game — habits that compound.', null)
  returning id
)
insert into public.education_lessons (chapter_id, progress_key, slug, title, minutes, intro, body, sort_order)
values
  ((select id from ch), 'b1', 'history-that-compounds', 'Building credit history that compounds', 5, 'A lot of credit improvement is fast — utilization can shift in a month. But the deepest, most durable gains come from history, and history only does one thing: it accumulates. Time is a lever too; it just works quietly.', '[{"h":"Why age matters"},{"p":"Length of credit history is one of the five factors. Scoring models generally reward a longer track record and a higher average account age, because more history means a more reliable prediction. You can’t rush this — but you can avoid sabotaging it, and you can set it up to compound."},{"h":"The compounding effect"},{"p":"Every month you keep good accounts open and in good standing, two things happen: your average account age ticks up, and your record of on-time payments grows longer. Neither is dramatic in any single month, but over years they become the backbone of a strong score — the part that’s hard for a setback to undo."},{"callout":"Think of your oldest accounts as the roots of your file. They don’t need attention — they just need to stay in the ground. The longer they’re there, the more stable everything above them becomes."},{"h":"Protecting your history"},{"list":["Keep old accounts open when reasonable — especially your oldest. Closing your longest-held card can lower your average age and reduce available credit at once.","If a card has no annual fee, there’s often little harm in keeping it open and using it occasionally to keep it active.","Avoid opening many new accounts in a short span — each new account lowers your average age and the newness counts against you briefly."]},{"h":"The patient mindset"},{"p":"Once your payment history and utilization are in good shape, much of what remains is simply <em>not interfering</em>. Let good accounts age. Keep paying on time. Resist the urge to constantly open and close things. The file strengthens on its own."},{"p":"This is also why starting sooner helps — not because anything is urgent, but because the clock that builds history only runs while accounts are open."},{"callout":"Takeaway: history compounds. Keep good accounts — especially old ones — open and in good standing, avoid churn, and let time do work that no quick tactic can replicate."}]'::jsonb, 0),
  ((select id from ch), 'b2', 'new-accounts-and-closures', 'How new accounts and closures move your score', 4, 'Opening and closing accounts both move your score, sometimes in ways that feel counterintuitive — like closing a paid-off card actually hurting. Here’s what each action does and why.', '[{"h":"What opening a new account does"},{"p":"Opening a new credit account generally has a few short-term effects:"},{"list":["A hard inquiry from the application — small and temporary.","It lowers your average account age, because a brand-new account drags the average down.","It adds available credit, which can <em>lower</em> your overall utilization — a potential plus."]},{"p":"So a new account is a mix: a small short-term cost (inquiry + younger average age) against a possible utilization benefit. One new account when you have a reason for it is generally minor. Several at once is what tends to weigh more."},{"h":"What closing an account does"},{"p":"Closing a card can feel responsible — but it can work against your score in two ways:"},{"steps":["It removes that card’s limit from your available credit, which <em>raises</em> your overall utilization (your balances are now divided by a smaller total limit).","Over time it can reduce your average account age, especially if it was an older card — and eventually the positive history may no longer help as it ages off."]},{"callout":"The counterintuitive part: paying off a card and then closing it can lower your score, because you’ve removed available credit and, eventually, history. Paid off doesn’t always mean close it."},{"h":"When closing can still make sense"},{"p":"None of this means never close anything. There are good reasons — a high annual fee you don’t use, a card tempting you to overspend, simplifying your finances, or a problematic account. The point is to close with awareness of the trade-off, not on the assumption that fewer cards is automatically “better” for your score."},{"p":"If you do close one, closing a newer card generally costs less history than closing your oldest. And paying down balances elsewhere first can blunt the utilization jump."},{"callout":"Takeaway: opening adds an inquiry and lowers average age but can help utilization; closing removes available credit (raising utilization) and eventually history. Open when you have a reason, and think twice before closing old, no-fee cards."}]'::jsonb, 1),
  ((select id from ch), 'b3', 'recovering-after-a-miss', 'Recovering after a missed payment or collection', 6, 'A missed payment or an account in collections feels like a permanent black mark. It isn’t. Negative items fade, and there are constructive steps you can take. Recovery is slower than damage — but it’s real.', '[{"h":"First, the reassurance"},{"p":"A single missed payment, or even a rough patch, is not the end of your credit. Negative information doesn’t stay forever — it ages off your report after a set period, and its weight on your score generally lessens over time even before it disappears. Meanwhile, new positive history starts counterbalancing it."},{"callout":"Time moves in your favour here. The further a negative event recedes into the past, the less it generally weighs — and steady positive behaviour after it accelerates the recovery."},{"h":"If you’ve just missed a payment"},{"steps":["Bring the account current as soon as you can — the longer it stays unpaid, the more serious the mark (30 days late is less severe than 90+).","Contact the lender. Some may, at their discretion, choose not to report a single isolated late payment, particularly if you have an otherwise good history — it’s reasonable to ask, though they’re not obligated.","Set up safeguards so it doesn’t repeat — reminders, or automatic minimum payments as a backstop."]},{"h":"If an account has gone to collections"},{"p":"A collection is more serious, but still recoverable. General points to understand:"},{"list":["Verify the debt is actually yours and the amount is correct before paying — errors happen, and you can dispute inaccurate collections.","Understand what paying does: a paid collection is generally viewed more favourably than an unpaid one, though the record of it may remain until it ages off.","Get any agreement about a collection account in writing before paying.","Because the stakes and rules can be complex, this is an area where advice specific to your situation — and your province or state — is worth seeking."]},{"h":"Rebuilding after the fact"},{"p":"The rebuild looks like the build: keep current accounts in perfect standing, keep utilization low, and let time pass. Each on-time month adds positive history that dilutes the old negative. The score recovers gradually, then more noticeably as the negative item ages."},{"callout":"Takeaway: missed payments and collections are setbacks, not permanent. Bring things current, address collections carefully (and get help for complex ones), then rebuild with on-time payments and low utilization. Time does the rest."}]'::jsonb, 2),
  ((select id from ch), 'b4', 'avoiding-credit-scams', 'Avoiding the common credit-repair scams', 5, 'Where there’s anxiety about credit, there are people selling shortcuts. Some “credit repair” offers are legitimate services; others are scams that charge for things you can do free, or promise things no one can deliver. Here’s how to tell the difference.', '[{"h":"The promises that should raise a flag"},{"p":"Be cautious of anyone who:"},{"list":["Guarantees a specific score increase, or a specific number, for a fee — no one can guarantee that.","Claims they can remove <em>accurate</em> negative information from your report — accurate items generally can’t be erased on demand; they age off over time.","Asks for a large upfront fee before doing anything.","Tells you not to contact the credit bureaus yourself.","Suggests creating a “new credit identity” or using a different identifying number — this can be illegal.","Pressures you to act immediately, or is vague about exactly what you’re paying for."]},{"callout":"A simple test: if an offer promises to delete true information or guarantees a number, be skeptical. Legitimate help is transparent about what it can and can’t do — and what it can do, you can often do yourself."},{"h":"What you can do yourself, for free"},{"p":"Much of what some services charge for is available to you directly at no cost:"},{"list":["Request and review your own credit reports from the bureaus.","Dispute genuine errors directly with Equifax or TransUnion.","Build positive history through your own accounts and on-time payments.","Wait out accurate negative items as they age off."]},{"h":"Where legitimate help fits"},{"p":"There are honest services and educational tools (including this one) that help you understand your file, organize your finances, and stay on track. The distinction is honesty about outcomes: a legitimate service helps you do the right things and understand your situation — it doesn’t promise to make accurate bad history vanish or guarantee a magic number."},{"h":"Protecting yourself"},{"steps":["Never pay a large upfront fee for vague “repair” promises.","Don’t share sensitive personal information with an unsolicited “repair” contact.","Be especially wary of anything suggesting you misrepresent your identity.","When in doubt, slow down — pressure to act fast is itself a warning sign."]},{"callout":"Takeaway: legitimate help is honest about limits; scams sell guarantees and deletions of true information. You can review your reports, dispute real errors, and build history yourself, for free. Guard your information and distrust urgency."}]'::jsonb, 3);

with ch as (
  insert into public.education_chapters (number, title, tagline, score_gate)
  values (4, 'Mortgage readiness', 'For when you’ve stabilized and want to optimize.', 700)
  returning id
)
insert into public.education_lessons (chapter_id, progress_key, slug, title, minutes, intro, body, sort_order)
values
  ((select id from ch), 'm1', 'beyond-the-score', 'What lenders look for beyond the score', 5, 'When you apply for a mortgage, your credit score matters — but it’s only one input. Lenders look at a fuller picture. Understanding what else they weigh helps you prepare the whole application, not just the number.', '[{"h":"The score opens the door; the file walks through it"},{"p":"A strong score generally helps you qualify and can affect the rate you’re offered. But mortgage lending involves a deeper review than a credit-card approval. Lenders are lending a large amount over a long time, so they look beyond the three-digit number."},{"h":"What lenders generally also consider"},{"list":["<strong>Income and its stability</strong> — not just how much, but how reliable and how well-documented it is.","<strong>Debt-to-income</strong> — how your existing obligations compare to your income (its own lesson follows).","<strong>Down payment</strong> — how much you’re putting in, and sometimes where it came from.","<strong>Employment history</strong> — a steady record is generally viewed favourably.","<strong>The full credit file</strong> — not just the score, but the detail: recent late payments, how much new credit you’ve taken on, the mix and age of accounts.","<strong>Savings and reserves</strong> — evidence you can handle payments and unexpected costs."]},{"callout":"A high score with a thin or shaky overall picture is weaker than it looks. Mortgage readiness is about the whole application hanging together — the score is necessary but not sufficient."},{"h":"Why recent behaviour matters extra"},{"p":"Close to a mortgage application, lenders pay particular attention to recent activity. A flurry of new accounts, a rising balance, or a recent late payment can raise questions even if your long-term history is strong. The stretch before applying is a time to keep things steady, not to make big credit moves."},{"h":"Preparing the whole picture"},{"p":"Getting mortgage-ready generally means tending to all of it: a strong score, a clean recent file, manageable debt relative to income, documented stable income, and savings. The next lessons go deeper on getting the file ready and on debt-to-income specifically."},{"p":"This is general education, not mortgage or financial advice — specific lender requirements vary, and a mortgage professional can speak to your situation."},{"callout":"Takeaway: the score gets you considered; income stability, debt-to-income, down payment, documented employment, savings, and the detail of your recent file decide the rest. Prepare the whole application, and keep recent activity calm."}]'::jsonb, 0),
  ((select id from ch), 'm2', 'file-mortgage-ready', 'Getting your file mortgage-ready', 6, 'In the months before a mortgage application, there’s a lot you can do to present the cleanest possible credit file — and a few common moves that quietly work against you. Preparation is mostly about steadiness.', '[{"h":"The goal: a calm, clean recent file"},{"p":"Mortgage lenders scrutinize the recent stretch of your credit closely. The aim in the lead-up is a file that looks stable and low-risk: on-time payments, low utilization, no sudden changes, no surprises. Think of it as tidying before an inspection."},{"h":"Generally helpful in the lead-up"},{"list":["Keep every payment on time — a recent late mark stands out most.","Bring utilization down — lower balances relative to limits present well, and it’s one of the faster things to improve.","Review your reports for errors well ahead of applying, so there’s time to dispute and resolve anything inaccurate.","Keep your existing accounts open and stable — continuity reads as stability.","Have your documentation in order — income, employment, and the source of your down payment."]},{"h":"Common moves to avoid before applying"},{"steps":["Opening new credit — a new card or loan adds an inquiry, lowers average account age, and introduces a fresh obligation right when the lender wants to see stability.","Making a large purchase on credit — it spikes utilization and adds debt at the worst time.","Closing old accounts — it can raise utilization and reduce history just before scrutiny.","Taking on a co-signed obligation or big new commitment that changes your debt picture.","Letting anything slip to late — even one missed payment can be costly this close to applying."]},{"callout":"The lead-up to a mortgage is a hold-steady period, not a build-aggressively one. The single best thing many people can do is simply not make sudden changes — no new accounts, no big purchases, no closures."},{"h":"Give yourself runway"},{"p":"Because disputes take time to resolve and utilization changes take a cycle or two to report, it helps to start tidying the file well before you plan to apply rather than in the final weeks. Earlier preparation means fewer surprises."},{"p":"As always, this is general guidance — a mortgage professional can advise on what a specific lender will want to see and when."}]'::jsonb, 1),
  ((select id from ch), 'm3', 'debt-to-income', 'Debt-to-income and how it’s assessed', 5, 'Debt-to-income is one of the numbers mortgage lenders care about most — and it’s separate from your credit score. You can have a great score and still be turned down if this ratio is out of line. Here’s how it works.', '[{"h":"What debt-to-income is"},{"p":"Debt-to-income (DTI) compares how much you owe to how much you earn. Broadly, it asks: of your income, how much is already committed to debt? Lenders use it to judge whether you can comfortably take on a mortgage payment on top of your existing obligations."},{"callout":"DTI is about capacity, not history. Your score says how reliably you’ve repaid; DTI says how much room you have to repay more. A mortgage lender wants both to look good."},{"h":"The two ratios lenders often use"},{"p":"Mortgage lending commonly looks at two related measures (the exact names and thresholds vary by country and lender):"},{"list":["A <strong>housing ratio</strong> — roughly, your expected housing costs compared to your income.","A <strong>total debt ratio</strong> — your housing costs <em>plus</em> your other debt payments (cards, loans, lines of credit) compared to your income."]},{"p":"In Canada these are often discussed as GDS (Gross Debt Service) and TDS (Total Debt Service); in the US as front-end and back-end DTI. The idea is the same: lenders set limits on how high these ratios can go."},{"h":"How to improve your DTI"},{"p":"Because DTI is a ratio of debt payments to income, you improve it by lowering the top or raising the bottom:"},{"steps":["Pay down existing debts — especially high-payment ones — to reduce your monthly obligations.","Avoid taking on new debt before applying, which would add to the numerator.","Increase documented income where possible — though lenders generally want stable, verifiable income, not one-off boosts.","Be realistic about the housing cost you’re targeting — a smaller payment keeps both ratios lower."]},{"h":"Why it sits alongside the score"},{"p":"A strong score and a healthy DTI tell a lender two different reassuring things: you repay reliably, and you have the capacity to take on more. Mortgage readiness generally means getting both in shape — which is why this chapter treats the score as the entry point, not the finish line."},{"callout":"Takeaway: DTI compares your debt payments to your income and measures capacity, separate from your score. Lower it by reducing existing debt and avoiding new obligations before applying. Lenders want a good score and a healthy DTI together. This is general information, not mortgage advice."}]'::jsonb, 2);
